// Set Scale, the presets and the labels of a scale (plan 5.4, tests-first). Windows source of truth: scales.py:4-74 (presets, format_custom_scale),
// set_scale_dialog.py:158-165 (the dialog's match), page_settings_bar.py:159-206 (the label the bar shows). No Windows test pins the preset tables or the match rules
// (register SS-7; "source only"): the tables below are the literals of scales.py, read by the oracle generator from the real module and checked by a count.
// Oracle rows: PageScaleLabelOracleData.hpp (generated by running scales.py read-only; CPython 3.11.4, python -B -I).
#include "FormattingTestSupport.hpp"

#include "Domain/PageScale.hpp"

#include "PageScaleLabelOracleData.hpp"

#include <cmath>
#include <limits>
#include <string>
#include <vector>

using namespace ost_domain;
using std::string;

namespace
{
    constexpr double kInfinity = std::numeric_limits<double>::infinity();
    constexpr double kNotANumber = std::numeric_limits<double>::quiet_NaN();
}

// ---- the preset tables (scales.py:4-55) -----------------------------------------------------------------------------------------------

// ARCH_SCALES (12), CIVIL_SCALES (11), METRIC_SCALES (17) in the Windows order with their labels; ALL_SCALES is the three lists in a row (40).
TEST(SetScale_Presets, TheThreeTablesAndAllScalesAreTheWindowsLists)
{
    REQUIRE_EQ(scale_presets(kScaleStyleArchitectural).size(), static_cast<size_t>(12));
    REQUIRE_EQ(scale_presets(kScaleStyleCivil).size(), static_cast<size_t>(11));
    REQUIRE_EQ(scale_presets(kScaleStyleMetric).size(), static_cast<size_t>(17));
    REQUIRE_EQ(all_scale_presets().size(), static_cast<size_t>(40));
    size_t flat = 0;
    for (const scale_oracle::ScalePresetRow &row : scale_oracle::kPresetRows)
    {
        SCOPED_CONTEXT("row " + std::to_string(flat) + " " + row.label);
        const std::vector<ScalePreset> &styled = scale_presets(row.style);
        size_t first_of_style = 0;
        for (const scale_oracle::ScalePresetRow &other : scale_oracle::kPresetRows)
        {
            if (other.style == row.style)
                break;
            ++first_of_style;
        }
        const size_t index = flat - first_of_style;
        REQUIRE(index < styled.size());
        CHECK_EQ(styled[index].sf1, row.sf1);
        CHECK_EQ(styled[index].sf2, row.sf2);
        CHECK_STR_EQ(styled[index].label, row.label);
        CHECK_EQ(all_scale_presets()[flat].sf1, row.sf1);
        CHECK_EQ(all_scale_presets()[flat].sf2, row.sf2);
        CHECK_STR_EQ(all_scale_presets()[flat].label, row.label);
        ++flat;
    }
    CHECK_EQ(flat, static_cast<size_t>(40));
}

// scales.py:4-55 spot checks, spelled out (so a wrong oracle generator cannot hide a wrong table): the first and last of each style and the two (1, 1) presets.
TEST(SetScale_Presets, TheLabelsOfTheKnownPresetsAreSpelledLikeWindows)
{
    const std::vector<ScalePreset> &arch = scale_presets(kScaleStyleArchitectural);
    REQUIRE_EQ(arch.size(), static_cast<size_t>(12)); // (the stub has no presets: stop here instead of reading an empty list)
    REQUIRE_EQ(scale_presets(kScaleStyleCivil).size(), static_cast<size_t>(11));
    REQUIRE_EQ(scale_presets(kScaleStyleMetric).size(), static_cast<size_t>(17));
    CHECK_STR_EQ(arch.front().label, "1/32\" = 1' 0\"");
    CHECK_EQ(arch.front().sf1, 0.03125);
    CHECK_EQ(arch.front().sf2, 12.0);
    CHECK_STR_EQ(arch[3].label, "1/8\" = 1' 0\"");
    CHECK_STR_EQ(arch[5].label, "1/4\" = 1' 0\"");
    CHECK_STR_EQ(arch[10].label, "1-1/2\" = 1' 0\"");
    CHECK_STR_EQ(arch.back().label, "3\" = 1' 0\"");
    const std::vector<ScalePreset> &civil = scale_presets(kScaleStyleCivil);
    CHECK_STR_EQ(civil.front().label, "1\" = 1\"");
    CHECK_STR_EQ(civil[2].label, "1\" = 20' 0\"");
    CHECK_STR_EQ(civil.back().label, "1\" = 100' 0\"");
    CHECK_EQ(civil.back().sf2, 1200.0);
    const std::vector<ScalePreset> &metric = scale_presets(kScaleStyleMetric);
    CHECK_STR_EQ(metric.front().label, "1 : 1000");
    CHECK_STR_EQ(metric[4].label, "1 : 100");
    CHECK_STR_EQ(metric[13].label, "1 : 1");
    CHECK_STR_EQ(metric[14].label, "10 : 1");
    CHECK_STR_EQ(metric.back().label, "50 : 1");
    CHECK_EQ(metric.back().sf1, 50.0);
    CHECK_EQ(metric.back().sf2, 1.0);
}

// A style without presets has an empty list (set_scale_dialog.py:171 SCALES_BY_STYLE.get(style_id, ())).
TEST(SetScale_Presets, AnUnknownStyleHasNoPresets)
{
    CHECK(scale_presets(0).empty());
    CHECK(scale_presets(4).empty());
    CHECK(scale_presets(-1).empty());
    CHECK(scale_presets(1000).empty());
    CHECK_EQ(scale_presets(kScaleStyleArchitectural).size(), static_cast<size_t>(12)); // the control: the three real styles are not empty
    CHECK_EQ(scale_presets(kScaleStyleMetric).size(), static_cast<size_t>(17));
}

// ---- the dialog's match (set_scale_dialog.py:158-165) ---------------------------------------------------------------------------------------

// Every row of kMatchRows (the real rule): styles 1, 2, 3 in this order, the first preset within 1e-9 (strict) on both values, else (style 1, index -1);
// (1.0, 1.0) matches Civil `1" = 1"` before Metric `1 : 1` (SS-7: a page saved as Metric 1 : 1 reopens as Civil), NaN matches nothing.
TEST(SetScale_Presets, FindMatchingPresetMatchesWindowsOnEveryRow)
{
    for (const scale_oracle::MatchRow &row : scale_oracle::kMatchRows)
    {
        SCOPED_CONTEXT("(" + ost_test::detail::exact_float(row.sf1) + ", " + ost_test::detail::exact_float(row.sf2) + ")");
        const PresetMatch got = find_matching_preset(row.sf1, row.sf2);
        CHECK_EQ(got.style, row.style);
        CHECK_EQ(got.index, row.index);
    }
}

// The tolerance is strict (< 1e-9 on EACH value) and absolute: 0.125 + 5e-10 matches, 0.125 + 2e-9 does not, 12 + 5e-10 matches, 12 - 2e-9 does not.
// (Review fix: the row `0.125 + 1e-9 does not match` was wrong. In IEEE double 0.125 + 1e-9 is 0.125000001 and abs(0.125 - (0.125 + 1e-9)) is 9.999999994736442e-10, BELOW 1e-9,
// so the real Windows rule `abs(a - b) < 1e-9` (set_scale_dialog.py:162-163), run with python -B -I, MATCHES it: that pair is pinned as it is, then a gap clearly above 1e-9.)
TEST(SetScale_Presets, TheMatchToleranceIsStrictAndAbsolute)
{
    CHECK_EQ(find_matching_preset(0.125 + 5e-10, 12.0).index, 3);
    CHECK_EQ(find_matching_preset(0.125 + 1e-9, 12.0).index, 3); // the double gap is 9.999999994736442e-10, below 1e-9
    CHECK_EQ(find_matching_preset(0.125 + 2e-9, 12.0).index, -1);
    CHECK_EQ(find_matching_preset(0.125, 12.0 + 5e-10).index, 3);
    CHECK_EQ(find_matching_preset(0.125, 12.0 - 2e-9).index, -1);
    CHECK_EQ(find_matching_preset(0.125, 12.0).style, kScaleStyleArchitectural);
    CHECK_EQ(find_matching_preset(1.0, 240.0).style, kScaleStyleCivil);
    CHECK_EQ(find_matching_preset(1.0, 100.0).style, kScaleStyleMetric);
    CHECK_EQ(find_matching_preset(kNotANumber, 12.0).index, -1);
    CHECK_EQ(find_matching_preset(kInfinity, kInfinity).index, -1);
}

// ---- the bar's label (page_settings_bar.py:159-206) -----------------------------------------------------------------------------------------

// Every row of kCustomLabelRows: format_custom_scale, the bar's first-match index over ALL_SCALES and the label the bar shows (preset label, else custom label, else "").
TEST(SetScale_Presets, LabelsMatchWindowsOnEveryOracleRow)
{
    for (const scale_oracle::CustomLabelRow &row : scale_oracle::kCustomLabelRows)
    {
        SCOPED_CONTEXT("(" + ost_test::detail::exact_float(row.sf1) + ", " + ost_test::detail::exact_float(row.sf2) + ")");
        CHECK_STR_EQ(format_custom_scale(row.sf1, row.sf2), row.label);
        CHECK_EQ(bar_preset_index(row.sf1, row.sf2), row.bar_index);
        CHECK_STR_EQ(scale_display_label(row.sf1, row.sf2), row.display);
    }
}

// ---- group B: tests/presentation/utils/test_scales.py -------------------------------------------------------------------------------------

// test_scales.py:8 test_invalid_nonpositive_and_nonfinite_values_have_no_label: 0, -1, NaN, infinity in either position give ""; the Windows None and "invalid" rows are
// Python typing and are dropped.
TEST(SetScale_Labels, InvalidNonpositiveAndNonfiniteValuesHaveNoLabel)
{
    for (const double invalid : {0.0, -1.0, kNotANumber, kInfinity, -kInfinity})
    {
        SCOPED_CONTEXT("invalid " + ost_test::detail::exact_float(invalid));
        CHECK_STR_EQ(format_custom_scale(invalid, 12.0), "");
        CHECK_STR_EQ(format_custom_scale(1.0, invalid), "");
    }
}

// test_scales.py:14 test_architectural_foot_and_general_ratio_are_distinct. The text row ("1.25", "1000") is numbers here.
TEST(SetScale_Labels, ArchitecturalFootAndGeneralRatioAreDistinct)
{
    CHECK_STR_EQ(format_custom_scale(0.125, 12.0), "0.125\" = 1' 0\"");
    CHECK_STR_EQ(format_custom_scale(1.0, 12.0 + 1e-10), "1\" = 1' 0\"");
    CHECK_STR_EQ(format_custom_scale(1.0, 120.0), "1 : 120");
    CHECK_STR_EQ(format_custom_scale(1.25, 1000.0), "1.25 : 1000");
}

// test_scales.py:20 test_small_custom_values_are_not_rounded_to_zero.
TEST(SetScale_Labels, SmallCustomValuesAreNotRoundedToZero)
{
    CHECK_STR_EQ(format_custom_scale(0.000000123456789, 1.0), "1.23456789e-07 : 1");
}

// test_scales.py:25 test_only_the_twelve_inch_ratio_uses_foot_notation (abs_tol 1e-9 around 12).
TEST(SetScale_Labels, OnlyTheTwelveInchRatioUsesFootNotation)
{
    CHECK_STR_EQ(format_custom_scale(2.0, 12.0), "2\" = 1' 0\"");
    CHECK_STR_EQ(format_custom_scale(1.0, 12.0000001), "1 : 12.0000001");
    CHECK_STR_EQ(format_custom_scale(1.0, 12.001), "1 : 12.001");
    CHECK_STR_EQ(format_custom_scale(1.0, 11.999), "1 : 11.999");
    CHECK_STR_EQ(format_custom_scale(1.0, 24.0), "1 : 24");
}

// test_scales.py:32 test_float_noise_is_trimmed_to_fifteen_significant_digits: 0.1 + 0.2 -> 0.3, 1234567.5, sixteen-plus digit inputs cut to fifteen.
TEST(SetScale_Labels, FloatNoiseIsTrimmedToFifteenSignificantDigits)
{
    CHECK_STR_EQ(format_custom_scale(0.1 + 0.2, 1.0), "0.3 : 1");
    CHECK_STR_EQ(format_custom_scale(1.0, 1.0), "1 : 1");
    CHECK_STR_EQ(format_custom_scale(1234567.5, 2.0), "1234567.5 : 2");
    CHECK_STR_EQ(format_custom_scale(0.123456789012345678, 1.0), "0.123456789012346 : 1");
    CHECK_STR_EQ(format_custom_scale(1.0, 1234567.12345678912), "1 : 1234567.12345679");
}

// ---- group K: tests/presentation/components/test_page_settings_bar.py -----------------------------------------------------------------------

// test_page_settings_bar.py:170 test_custom_scale_display_tracks_page_refresh_without_emitting_requests: a custom (0.26, 12) shows `0.26" = 1' 0"`, (0.3751, 12) shows
// `0.3751" = 1' 0"`, loading the same value again (also 0.26000000000000001, the same double) shows the same text. (The combo's item count and the Qt signals are widget state.)
TEST(SetScale_Bar, CustomScaleDisplayTracksPageRefresh)
{
    for (int i = 0; i < 12; ++i)
        CHECK_STR_EQ(scale_display_label(0.26, 12.0), "0.26\" = 1' 0\"");
    CHECK_STR_EQ(scale_display_label(0.3751, 12.0), "0.3751\" = 1' 0\"");
    CHECK_STR_EQ(scale_display_label(0.26000000000000001, 12.0), "0.26\" = 1' 0\"");
    CHECK_EQ(bar_preset_index(0.26, 12.0), -1); // a custom scale selects the last "Custom scale" item, not a preset
}

// test_page_settings_bar.py:196 test_switching_between_custom_and_predefined_resets_one_custom_item: a custom page shows its custom label, the next page (0.125, 12) shows the
// preset `1/8" = 1' 0"` (no custom label), and the custom page again shows its custom label.
TEST(SetScale_Bar, SwitchingBetweenCustomAndPredefinedShowsTheRightLabel)
{
    CHECK_STR_EQ(scale_display_label(0.26, 12.0), "0.26\" = 1' 0\"");
    CHECK_STR_EQ(scale_display_label(0.125, 12.0), "1/8\" = 1' 0\"");
    CHECK_EQ(bar_preset_index(0.125, 12.0), 3);
    CHECK_STR_EQ(scale_display_label(0.26, 12.0), "0.26\" = 1' 0\"");
}

// test_page_settings_bar.py:209 test_predefined_and_reloaded_scale_labels_remain_readable: (1, 240) `1" = 20' 0"`, (0.125, 12) `1/8" = 1' 0"`, (0.1875, 12) `3/16" = 1' 0"`.
TEST(SetScale_Bar, PredefinedScaleLabelsRemainReadable)
{
    CHECK_STR_EQ(scale_display_label(1.0, 240.0), "1\" = 20' 0\"");
    CHECK_STR_EQ(scale_display_label(0.125, 12.0), "1/8\" = 1' 0\"");
    CHECK_STR_EQ(scale_display_label(0.1875, 12.0), "3/16\" = 1' 0\"");
}

// test_page_settings_bar.py:295 test_non_architectural_custom_and_invalid_scales_use_safe_display: (2.5, 1000) shows `2.5 : 1000`; (None | 0 | -0.26 | NaN | "x", 12) and
// (0.26, 0 | -12 | inf) select nothing and show "". The None and "not-a-number" text rows are Python typing and are dropped (None is the 0 row).
TEST(SetScale_Bar, NonArchitecturalCustomAndInvalidScalesUseSafeDisplay)
{
    CHECK_STR_EQ(scale_display_label(2.5, 1000.0), "2.5 : 1000");
    CHECK_EQ(bar_preset_index(2.5, 1000.0), -1);
    const struct
    {
        double sf1;
        double sf2;
    } invalid[] = {{0.0, 12.0}, {0.26, 0.0}, {-0.26, 12.0}, {0.26, -12.0}, {kNotANumber, 12.0}, {0.26, kInfinity}};
    for (const auto &pair : invalid)
    {
        SCOPED_CONTEXT("(" + ost_test::detail::exact_float(pair.sf1) + ", " + ost_test::detail::exact_float(pair.sf2) + ")");
        CHECK_EQ(bar_preset_index(pair.sf1, pair.sf2), -1);
        CHECK_STR_EQ(scale_display_label(pair.sf1, pair.sf2), "");
    }
}

// The bar matches against ALL_SCALES in one list: its index runs over the 40 entries (Civil starts at 12, Metric at 23) and the first entry wins for (1, 1) (Civil, index 12).
TEST(SetScale_Bar, TheBarIndexRunsOverAllFortyPresetsAndTheFirstWins)
{
    CHECK_EQ(bar_preset_index(0.03125, 12.0), 0);
    CHECK_EQ(bar_preset_index(3.0, 12.0), 11);
    CHECK_EQ(bar_preset_index(1.0, 1.0), 12);     // Civil `1" = 1"` before Metric `1 : 1` (index 36)
    CHECK_EQ(bar_preset_index(1.0, 1200.0), 22);
    CHECK_EQ(bar_preset_index(1.0, 1000.0), 23);  // Metric `1 : 1000`
    CHECK_EQ(bar_preset_index(50.0, 1.0), 39);
    CHECK_STR_EQ(scale_display_label(1.0, 1.0), "1\" = 1\"");
}
